                     .append('"');
         }
         int transition = (int) Math.round(node.f32Property(Properties.TRANSITION, 0.0f));
         if (transition != 0) {
             String name = switch (transition) {
                 case 2 -> "fade";
                 case 3 -> "slide";
                 case 4 -> "scale";
