package dev.pathland.docs

import dev.pathland.view.core.AttributedString
import dev.pathland.view.core.Color as CoreColor
import dev.pathland.view.core.FontDesign
import dev.pathland.view.core.FontWeight
import dev.pathland.view.core.Roles
import dev.pathland.view.core.ScrollAxis
import dev.pathland.view.core.TextAlignment
import dev.pathland.view.core.VerticalAlignment
import dev.pathland.view.core.View
import dev.pathland.view.core.WhiteSpace
import dev.pathland.view.dsl.Button
import dev.pathland.view.dsl.Color
import dev.pathland.view.dsl.Divider
import dev.pathland.view.dsl.Font
import dev.pathland.view.dsl.Grid
import dev.pathland.view.dsl.GridRow
import dev.pathland.view.dsl.HStack
import dev.pathland.view.dsl.Image
import dev.pathland.view.dsl.ScrollView
import dev.pathland.view.dsl.Text
import dev.pathland.view.dsl.VStack
import dev.pathland.view.dsl.accessibilityLabel
import dev.pathland.view.dsl.accessibilityRole
import dev.pathland.view.dsl.anchor
import dev.pathland.view.dsl.background
import dev.pathland.view.dsl.border
import dev.pathland.view.dsl.font
import dev.pathland.view.dsl.fontDesign
import dev.pathland.view.dsl.fontSize
import dev.pathland.view.dsl.fontWeight
import dev.pathland.view.dsl.foregroundStyle
import dev.pathland.view.dsl.frame
import dev.pathland.view.dsl.multilineTextAlignment
import dev.pathland.view.dsl.padding
import dev.pathland.view.dsl.scaledToFit
import dev.pathland.view.dsl.whiteSpace
import org.commonmark.ext.gfm.strikethrough.Strikethrough
import org.commonmark.ext.gfm.strikethrough.StrikethroughExtension
import org.commonmark.ext.gfm.tables.TableBlock
import org.commonmark.ext.gfm.tables.TableBody
import org.commonmark.ext.gfm.tables.TableCell
import org.commonmark.ext.gfm.tables.TableHead
import org.commonmark.ext.gfm.tables.TableRow
import org.commonmark.ext.gfm.tables.TablesExtension
import org.commonmark.node.BlockQuote
import org.commonmark.node.BulletList
import org.commonmark.node.Code
import org.commonmark.node.Emphasis
import org.commonmark.node.FencedCodeBlock
import org.commonmark.node.HardLineBreak
import org.commonmark.node.Heading
import org.commonmark.node.HtmlBlock
import org.commonmark.node.HtmlInline
import org.commonmark.node.Image as MdImage
import org.commonmark.node.IndentedCodeBlock
import org.commonmark.node.Link
import org.commonmark.node.ListItem
import org.commonmark.node.Node
import org.commonmark.node.OrderedList
import org.commonmark.node.Paragraph
import org.commonmark.node.SoftLineBreak
import org.commonmark.node.StrongEmphasis
import org.commonmark.node.Text as MdText
import org.commonmark.node.ThematicBreak
import org.commonmark.parser.Parser

/** Options for [Markdown]. */
data class MarkdownOptions(
    /** Emit stable heading anchors + ids (needed by the docs TOC). */
    val headingIds: Boolean = true,
    /** Shift Markdown heading levels (e.g. `+1` when the page already has an H1). */
    val headingOffset: Int = 0,
    /** Vertical space between blocks. */
    val blockSpacing: Float = 12f,
    /** Prefix for relative image sources (`/docs-assets/` etc.). */
    val imageBase: String = "",
    /** Rewrite link targets (e.g. resolve a relative `.md` link to a route). */
    val linkResolver: (String) -> String = { it },
)

/**
 * Render block Markdown into a Kotlin DSL view tree.
 *
 * This is the docs content entry point. It parses with CommonMark + GFM tables
 * and emits Pathland views; it never renders HTML directly.
 */
@JvmOverloads
fun Markdown(markdown: String, options: MarkdownOptions = MarkdownOptions()): View {
    val parser = Parser.builder()
        .extensions(listOf(TablesExtension.create(), StrikethroughExtension.create()))
        .build()
    val document = parser.parse(markdown)
    return VStack(spacing = options.blockSpacing) {
        val slugger = Slugger()
        for (block in childNodes(document)) {
            renderBlock(block, options, slugger)
        }
    }
}

private fun renderBlock(node: Node, options: MarkdownOptions, slugger: Slugger) {
    when (node) {
        is Heading -> {
            val level = (node.level + options.headingOffset).coerceIn(1, 6)
            val text = inline(node, options)
            var view: View = Text(text).font(headingFont(level))
            if (options.headingIds) {
                view = view.anchor(slugger.slug(MarkdownHeadings.plain(text.text)))
            }
            view.accessibilityRole(Roles.HEADER)
        }

        is Paragraph -> {
            val onlyImage = singleImage(node)
            if (onlyImage != null) {
                renderImage(onlyImage, options)
            } else {
                Text(inline(node, options)).accessibilityRole(Roles.PARAGRAPH)
            }
        }

        is BulletList -> renderList(node, ordered = false, options = options, slugger = slugger)
        is OrderedList -> renderList(node, ordered = true, options = options, slugger = slugger)

        is FencedCodeBlock ->
            CodeBlock(node.literal, node.info?.trim()?.substringBefore(' '))

        is IndentedCodeBlock -> CodeBlock(node.literal, null)

        is BlockQuote -> {
            HStack(alignment = VerticalAlignment.TOP, spacing = 12f) {
                Color(CoreColor.token("color.border")).frame(width = 4f)
                VStack(spacing = 8f) {
                    for (child in childNodes(node)) {
                        renderBlock(child, options, slugger)
                    }
                }
            }.padding(top = 4f, right = 0f, bottom = 4f, left = 0f)
        }

        is ThematicBreak -> Divider()

        is TableBlock -> renderTable(node, options)

        is HtmlBlock -> Text(node.literal, markdown = false)

        else -> {
            if (node.firstChild != null) {
                VStack(spacing = 8f) {
                    for (child in childNodes(node)) {
                        renderBlock(child, options, slugger)
                    }
                }
            }
        }
    }
}

private fun renderList(
    node: Node,
    ordered: Boolean,
    options: MarkdownOptions,
    slugger: Slugger,
) {
    var index = if (node is OrderedList) node.startNumber else 1
    VStack(spacing = 6f) {
        for (item in childNodes(node)) {
            val marker = if (ordered) "$index." else "•"
            HStack(alignment = VerticalAlignment.TOP, spacing = 8f) {
                Text(marker).fontSize(15f).foregroundStyle(CoreColor.token("color.text.secondary"))
                VStack(spacing = 4f) {
                    for (child in childNodes(item)) {
                        renderBlock(child, options, slugger)
                    }
                }
            }.accessibilityRole(Roles.LIST_ITEM)
            if (item is ListItem && ordered) index += 1
        }
    }.accessibilityRole(Roles.LIST)
}

private fun renderImage(image: MdImage, options: MarkdownOptions) {
    val src = resolveImage(image.destination, options)
    val alt = image.altText()
    Image(src)
        .accessibilityLabel(alt)
        .scaledToFit()
        .frame { maxWidth(1000f) }
}

private fun renderTable(table: TableBlock, options: MarkdownOptions) {
    val rows = ArrayList<TableRow>()
    for (child in childNodes(table)) {
        when (child) {
            is TableHead -> collectRows(child, rows)
            is TableBody -> collectRows(child, rows)
            is TableRow -> rows.add(child)
        }
    }
    val columns = rows.maxOfOrNull { row -> countCells(row) } ?: 0
    if (columns == 0) return

    ScrollView(axis = ScrollAxis.HORIZONTAL) {
        Grid(columns = columns, spacing = 0f) {
            for (row in rows) {
                GridRow {
                    var column = 0
                    for (cell in childNodes(row)) {
                        if (cell !is TableCell) continue
                        val alignment = when (cell.alignment) {
                            TableCell.Alignment.CENTER -> TextAlignment.CENTER
                            TableCell.Alignment.RIGHT -> TextAlignment.TRAILING
                            else -> TextAlignment.LEADING
                        }
                        var cellView: View = Text(inline(cell, options))
                            .multilineTextAlignment(alignment)
                            .padding(8f)
                            .border(CoreColor.token("color.border"), 1f)
                        if (cell.isHeader) {
                            cellView = cellView
                                .background(CoreColor.token("color.surface"))
                                .fontWeight(FontWeight.BOLD)
                        }
                        cellView
                        column++
                    }
                    while (column < columns) {
                        Text("").padding(8f).border(CoreColor.token("color.border"), 1f)
                        column++
                    }
                }
            }
        }.accessibilityLabel("Table")
    }
}

private fun collectRows(node: Node, out: MutableList<TableRow>) {
    for (child in childNodes(node)) {
        if (child is TableRow) out.add(child)
    }
}

private fun countCells(row: TableRow): Int {
    var count = 0
    for (cell in childNodes(row)) {
        if (cell is TableCell) count++
    }
    return count
}

/** A monospace code block with preserved whitespace (no syntax highlighting). */
@JvmOverloads
fun CodeBlock(code: String, language: String? = null, wrap: Boolean = false): View {
    VStack(spacing = 0f) {
        if (!language.isNullOrBlank()) {
            Text(language).fontSize(11f)
                .foregroundStyle(CoreColor.token("color.text.secondary"))
                .padding(top = 6f, right = 12f, bottom = 0f, left = 12f)
        }
        ScrollView(axis = ScrollAxis.HORIZONTAL) {
            Text(code.trimEnd('\n'), markdown = false)
                .fontDesign(FontDesign.MONOSPACED)
                .fontSize(13f)
                .whiteSpace(if (wrap) WhiteSpace.PRE_WRAP else WhiteSpace.PRE)
                .padding(12f)
        }
    }.background(CoreColor.token("color.surface"))
        .border(CoreColor.token("color.border"), 1f, 8f)
}

private fun headingFont(level: Int): Font = when (level) {
    1 -> Font.largeTitle()
    2 -> Font.title()
    3 -> Font.title2()
    4 -> Font.title3()
    else -> Font.headline()
}

private fun singleImage(paragraph: Paragraph): MdImage? {
    var only: Node? = null
    for (child in childNodes(paragraph)) {
        if (child is SoftLineBreak || child is HardLineBreak) continue
        if (only != null) return null
        only = child
    }
    return only as? MdImage
}

private fun resolveImage(destination: String, options: MarkdownOptions): String {
    if (destination.startsWith("http://") || destination.startsWith("https://") ||
        destination.startsWith("/")
    ) {
        return destination
    }
    return options.imageBase.trimEnd('/') + "/" + destination.trimStart('/')
}

private fun MdImage.altText(): String = buildString {
    for (child in childNodes(this@altText)) {
        append(NodeText.plain(child))
    }
}

private fun inline(node: Node, options: MarkdownOptions): AttributedString {
    val builder = AttributedString.builder()
    var length = 0

    fun append(value: String) {
        builder.append(value)
        length += value.length
    }

    fun walk(current: Node) {
        when (current) {
            is MdText -> append(current.literal)
            is Emphasis -> {
                val start = length
                walkChildren(current, ::walk)
                builder.italic(start, length)
            }
            is StrongEmphasis -> {
                val start = length
                walkChildren(current, ::walk)
                builder.bold(start, length)
            }
            is Strikethrough -> {
                val start = length
                walkChildren(current, ::walk)
                builder.strikethrough(start, length)
            }
            is Code -> {
                val start = length
                append(current.literal)
                builder.monospaced(start, length)
            }
            is Link -> {
                val start = length
                walkChildren(current, ::walk)
                builder.link(start, length, options.linkResolver(current.destination))
            }
            is MdImage -> walkChildren(current, ::walk)
            is SoftLineBreak, is HardLineBreak -> append("\n")
            is HtmlInline -> append(current.literal)
            else -> {
                if (current.firstChild != null) {
                    walkChildren(current, ::walk)
                }
            }
        }
    }

    walkChildren(node, ::walk)
    return builder.build()
}

private fun walkChildren(node: Node, visit: (Node) -> Unit) {
    for (child in childNodes(node)) {
        visit(child)
    }
}

private fun childNodes(node: Node): Sequence<Node> = sequence {
    var child = node.firstChild
    while (child != null) {
        yield(child)
        child = child.next
    }
}

private object NodeText {
    fun plain(node: Node): String = when (node) {
        is MdText -> node.literal
        is SoftLineBreak, is HardLineBreak -> " "
        else -> buildString {
            for (child in childNodes(node)) {
                append(plain(child))
            }
        }
    }
}

